  await walkComments(orgId, issueId, (comment) =>
    removeFromIndex(orgId, "comment", comment.id),
  );
}

/** Drops a project's document and those of every issue and comment under it. */
async function removeProjectTree(orgId: OrgId, projectId: Project["id"]) {
  await removeFromIndex(orgId, "project", projectId);
  await walkProjectIssues(orgId, projectId, (issue) =>
    removeIssueTree(orgId, issue.id),
  );
}

/**
 * Re-evaluates a project and everything under it. Issues that stayed archived
 * (with the project or before it) are dropped by `indexIssue`, and their
 * comments are not visited, so they stay hidden.
 */
async function reindexProjectTree(orgId: OrgId, project: Project) {
  await indexProject(orgId, project);
  await walkProjectIssues(orgId, project.id, async (issue) => {
    await indexIssue(orgId, issue);
    if (issue.archivedAt !== null) return;
    await walkComments(orgId, issue.id, (comment) =>
      indexComment(orgId, comment),
    );
  });
}

